let LS='systemESG31:guest';
function readState(key){try{const x=JSON.parse(localStorage.getItem(key)||'null');if(!x||typeof x!=='object'||Array.isArray(x))return null;return {schema_version:4.1,cloud_reset_version:Number(x.cloud_reset_version)||0,answered:x.answered||{},learned:x.learned||{},wrong:x.wrong||{},exams:Array.isArray(x.exams)?x.exams:[],attempts:Array.isArray(x.attempts)?x.attempts:[],past37:x.past37&&typeof x.past37==='object'?x.past37:{answers:{}}};}catch(e){return null;}}
let state=readState(LS)||readState('esgCarbonV4Final')||{schema_version:4.1,cloud_reset_version:0,answered:{},learned:{},wrong:{},exams:[],attempts:[],past37:{answers:{}}};
function save(){try{localStorage.setItem(LS,JSON.stringify(state));}catch(e){toast('保存失败，请导出进度备份');}updateDash();}
