function go(id){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));title.textContent=titles[id][0];desc.textContent=titles[id][1];if(id==='wrong')renderWrong();if(id==='ability')renderAbility();if(id==='sources')renderSources();window.scrollTo(0,0)}
document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));
function fillSelect(id,all=true){let s=document.getElementById(id);s.innerHTML=(all?'<option value="">全部模块</option>':'')+MODULES.map(m=>`<option value="${m.id}">${m.icon} ${m.name}</option>`).join('')}
fillSelect('learnModule');fillSelect('pModule');
function moduleStats(mid){let qs=QUESTIONS.filter(q=>q.module===mid),ans=qs.filter(q=>state.answered[q.id]);let cor=ans.filter(q=>state.answered[q.id].correct).length;let m=MODULES.find(x=>x.id===mid);let learned=m.nodes.filter(n=>state.learned[mid+'|'+n[0]]).length;return {q:qs.length,ans:ans.length,cor,acc:ans.length?Math.round(cor/ans.length*100):0,learned,total:m.nodes.length}}
function updateDash(){mKp.textContent=MODULES.reduce((a,m)=>a+m.nodes.length,0);mQ.textContent=QUESTIONS.length.toLocaleString();let eq=document.getElementById('engineQCount'),ek=document.getElementById('engineKpCount');if(eq)eq.textContent=QUESTIONS.length.toLocaleString();if(ek)ek.textContent=MODULES.reduce((a,m)=>a+m.nodes.length,0);let answered=Object.keys(state.answered).length,correct=Object.values(state.answered).filter(x=>x.correct).length,wrong=Object.keys(state.wrong).length,learned=Object.keys(state.learned).length,total=MODULES.reduce((a,m)=>a+m.nodes.length,0);mDone.textContent=answered;mWrong.textContent=wrong;mAcc.textContent=`正确率 ${answered?Math.round(correct/answered*100):0}%`;heroProg.textContent=Math.round(learned/total*100)+'%';moduleCards.innerHTML=MODULES.map(m=>{let s=moduleStats(m.id),p=Math.round(s.learned/s.total*100);return `<div class="card module" data-onclick="openModule('${m.id}')"><div class="mrow"><div><span class="pill">${s.q}题</span><h3>${m.icon} ${m.name}</h3></div><b>${p}%</b></div><p style="color:var(--muted);font-size:12.5px;line-height:1.5">${m.desc}</p><div class="bar"><i style="width:${p}%"></i></div><small>已学 ${s.learned}/${s.total} · 作答 ${s.ans} · 正确率 ${s.acc}%</small></div>`}).join('')}
function openModule(mid){go('learn');learnModule.value=mid;renderLearnList()}
function renderLearnList(){let mid=learnModule.value,q=learnSearch.value.trim();let arr=[];MODULES.filter(m=>!mid||m.id===mid).forEach(m=>m.nodes.forEach((n,i)=>{if(!q||n.join(' ').includes(q))arr.push({m,n,i})}));kpDetail.classList.add('hidden');kpList.innerHTML=arr.map(x=>{let key=x.m.id+'|'+x.n[0],done=state.learned[key];return `<div class="card kp" data-onclick="openKP('${x.m.id}',${x.i})"><div class="mrow"><span class="pill">${x.m.icon} ${x.m.name}</span><span>${done?'✅':'◻️'}</span></div><h4>${x.n[0]}</h4><p>${x.n[1]}</p><div class="foot"><small>${x.n[4]}</small><b>查看 →</b></div></div>`}).join('')||'<div class="empty">没有符合条件的知识点。</div>'}
learnSearch.oninput=renderLearnList;learnModule.onchange=renderLearnList;
function openKP(mid,i){let m=MODULES.find(x=>x.id===mid),n=m.nodes[i],key=mid+'|'+n[0],related=QUESTIONS.filter(q=>q.module===mid&&q.kp===n[0]).length;kpDetail.innerHTML=`<div class="learn-detail"><div class="card"><span class="pill">${m.icon} ${m.name}</span><h2>${n[0]}</h2><p>${n[1]}</p><div class="note"><b>核心知识</b><br>${n[2]}</div><div class="note" style="margin-top:10px"><b>关键提醒</b><br>${n[3]}</div><div class="tags" style="margin-top:12px">${n[4].split('、').map(t=>`<span class="pill">${t}</span>`).join('')}</div><p><button class="btn primary" data-onclick="markLearned('${key}')">${state.learned[key]?'已完成学习 ✓':'标记为已学习'}</button> <button class="btn soft" data-onclick="practiceKP('${mid}','${n[0].replaceAll("'","\\'")}')">练习本考点（${related}题）</button></p></div><div class="card src"><div class="k">来源体系</div><h3>${m.source}</h3><p>${m.desc}</p><p><a href="${m.url}" target="_blank" rel="noopener">打开官方/权威来源 ↗</a></p><hr style="border:0;border-top:1px solid var(--line)"><p><b>学习建议</b></p><p>先理解核心知识，再做 L1/L2；正确率稳定后进入 L3/L4 情境与实务题。</p></div></div>`;kpDetail.classList.remove('hidden');kpDetail.scrollIntoView({behavior:'smooth'})}
function markLearned(key){state.learned[key]=true;save();toast('已记录学习进度');renderLearnList()}
let pool=[],pi=0,selected=null;
function startPractice(custom){pool=custom||QUESTIONS.filter(q=>(!pModule.value||q.module===pModule.value)&&(!pLevel.value||q.level===pLevel.value)&&(!pType.value||q.type===pType.value)&&(!pOrigin.value||q.origin===pOrigin.value));pool=[...pool].sort(()=>Math.random()-.5);pi=0;renderPractice()}
function practiceKP(mid,kp){go('practice');pModule.value=mid;pLevel.value='';pType.value='';startPractice(QUESTIONS.filter(q=>q.module===mid&&q.kp===kp))}
function renderPractice(){if(!pool.length){practiceCard.innerHTML='<div class="empty">没有符合当前条件的题目。</div>';return}let q=pool[pi%pool.length],m=MODULES.find(x=>x.id===q.module),tag=q.origin.toLowerCase();selected=null;practiceCard.innerHTML=`<div class="tags"><span class="pill">${m.icon} ${m.name}</span><span class="pill">${q.kp}</span><span class="pill">${q.level}</span><span class="pill ${tag}">${q.origin}</span><span class="pill">${q.id}</span></div><div class="q">${q.q}</div><div class="opts">${q.options.map((o,i)=>`<div class="opt" data-onclick="choosePractice(${i})">${String.fromCharCode(65+i)}. ${o}</div>`).join('')}</div><div class="answer" id="pAnswer"></div><div class="qnav"><small>${pi+1}/${pool.length}</small><button class="btn primary" data-onclick="nextPractice()">下一题</button></div>`}
function choosePractice(i){let q=pool[pi%pool.length];if(selected!==null)return;selected=i;let correct=i===q.answer;document.querySelectorAll('#practiceCard .opt').forEach((el,j)=>el.classList.add(j===q.answer?'good':(j===i&&!correct?'bad':'')));pAnswer.innerHTML=`<b>${correct?'回答正确 ✓':'回答错误 ✕'}｜正确答案 ${String.fromCharCode(65+q.answer)}</b><br>${q.explain}<br><small>来源体系：${q.source}</small>`;pAnswer.style.display='block';state.answered[q.id]={correct,at:Date.now(),module:q.module,kp:q.kp};if(correct)delete state.wrong[q.id];else state.wrong[q.id]=true;save()}
function nextPractice(){if(selected===null){toast('请先作答');return}pi=(pi+1)%pool.length;renderPractice()}
function practiceWrong(){let qs=QUESTIONS.filter(q=>state.wrong[q.id]);if(!qs.length){toast('目前没有错题');return}go('practice');startPractice(qs)}
let exam={};
function stratified(n){let out=[],mods=[...MODULES];let per=Math.floor(n/mods.length),rem=n%mods.length;mods.forEach((m,idx)=>{let k=per+(idx<rem?1:0),arr=QUESTIONS.filter(q=>q.module===m.id).sort(()=>Math.random()-.5);out.push(...arr.slice(0,k))});return out.sort(()=>Math.random()-.5).slice(0,n)}
function startExam(n,min){exam={qs:stratified(n),i:0,ans:{},end:Date.now()+min*60000,timer:null};examSetup.classList.add('hidden');examResult.classList.add('hidden');examRun.classList.remove('hidden');renderExamQ();exam.timer=setInterval(tick,1000);tick()}
function tick(){if(!exam.end)return;let d=Math.max(0,exam.end-Date.now()),mm=Math.floor(d/60000),ss=Math.floor((d%60000)/1000),el=document.getElementById('timer');if(el)el.textContent=`${mm}:${String(ss).padStart(2,'0')}`;if(d<=0){clearInterval(exam.timer);finishExam()}}
function renderExamQ(){let q=exam.qs[exam.i],m=MODULES.find(x=>x.id===q.module),sel=exam.ans[q.id];examRun.innerHTML=`<div class="card"><div class="mrow"><div class="tags"><span class="pill">${m.name}</span><span class="pill">${q.level}</span><span class="pill">${exam.i+1}/${exam.qs.length}</span></div><div class="timer" id="timer"></div></div><div class="q">${q.q}</div><div class="opts">${q.options.map((o,i)=>`<div class="opt ${sel===i?'chosen':''}" data-onclick="answerExam(${i})">${String.fromCharCode(65+i)}. ${o}</div>`).join('')}</div><div class="qnav"><button class="btn soft" data-onclick="examPrev()">上一题</button><div><button class="btn soft" data-onclick="examNext()">下一题</button> <button class="btn primary" data-onclick="finishExam()">交卷</button></div></div></div>`;tick()}
function answerExam(i){let q=exam.qs[exam.i];exam.ans[q.id]=i;renderExamQ()}
function examNext(){if(exam.i<exam.qs.length-1){exam.i++;renderExamQ()}else toast('已经是最后一题')}
function examPrev(){if(exam.i>0){exam.i--;renderExamQ()}}
function finishExam(){if(!exam.qs)return;clearInterval(exam.timer);let cor=0,by={};exam.qs.forEach(q=>{let ok=exam.ans[q.id]===q.answer;if(ok)cor++;state.answered[q.id]={correct:ok,at:Date.now(),module:q.module,kp:q.kp};if(ok)delete state.wrong[q.id];else state.wrong[q.id]=true;by[q.module]??={n:0,c:0};by[q.module].n++;if(ok)by[q.module].c++});let score=Math.round(cor/exam.qs.length*100);state.exams.push({at:Date.now(),score,n:exam.qs.length});save();examRun.classList.add('hidden');examResult.classList.remove('hidden');examResult.innerHTML=`<div class="card resultHero"><div class="k">模拟考试结果</div><div class="score">${score}</div><p>${cor}/${exam.qs.length} 题正确</p><button class="btn primary" data-onclick="resetExam()">返回考试首页</button></div><div class="card section"><div class="head"><h3>模块拆解</h3></div>${Object.entries(by).map(([id,s])=>{let m=MODULES.find(x=>x.id===id),p=Math.round(s.c/s.n*100);return `<div style="margin:12px 0"><div class="mrow"><span>${m.icon} ${m.name}</span><b>${p}%</b></div><div class="bar"><i style="width:${p}%"></i></div></div>`}).join('')}</div>`}
function resetExam(){examResult.classList.add('hidden');examSetup.classList.remove('hidden')}
function renderWrong(){let qs=QUESTIONS.filter(q=>state.wrong[q.id]);wCount.textContent=qs.length;wKp.textContent=new Set(qs.map(q=>q.kp)).size;wrongList.innerHTML=qs.length?`<div class="head"><h3>错题清单</h3><span>按最近状态保留</span></div>`+qs.slice(0,80).map(q=>`<div class="wrongrow"><b>${q.id}｜${q.kp}</b><br><small>${q.q}</small></div>`).join(''):'<div class="empty">暂无错题，继续保持。</div>'}
function renderAbility(){abilityList.innerHTML=MODULES.map(m=>{let s=moduleStats(m.id),p=s.ans?s.acc:0;return `<div style="margin:14px 0"><div class="mrow"><span>${m.icon} ${m.name}<small style="color:var(--muted)"> · ${s.ans}/${s.q}题</small></span><b>${p}%</b></div><div class="bar"><i style="width:${p}%"></i></div></div>`}).join('')}
function renderSources(){sourceCards.innerHTML=MODULES.map(m=>`<div class="card src"><div class="mrow"><div><span class="micon">${m.icon}</span><h3>${m.name}</h3></div><span class="pill">${m.nodes.length}知识点</span></div><p>${m.source}</p><a href="${m.url}" target="_blank" rel="noopener">查看来源 ↗</a></div>`).join('')}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1600)}
renderLearnList();updateDash();

