function masteryRows31(){const map=new Map();for(const a of state.attempts||[]){if(!map.has(a.knowledge_id))map.set(a.knowledge_id,[]);map.get(a.knowledge_id).push(a);}return [...map].map(([knowledge_id,a])=>{const recent=a.slice(-20),mastery=Math.round(100*recent.filter(x=>x.correct).length/recent.length);return {knowledge_id,attempts:a.length,wrong:recent.filter(x=>!x.correct).length,mastery,recommendation:recent.length<5?'继续练习以积累证据':mastery<80?'回补知识点后再练':'进入更高难度'};}).sort((a,b)=>a.mastery-b.mastery);}
