function renderDemo31(){const i=Number(el('demoType').value),q=demos[i];el('demoQuestion').innerHTML=`<p>${esc(q.text)}</p>`+([0,1,3,5].includes(i)?q.options.map((o,n)=>`<label style="display:block;padding:8px"><input name="demoChoice" type="${i===1?'checkbox':'radio'}" value="${n}"> ${esc(o)}</label>`).join(''):i===4?q.options.map((o,n)=>`<p>${n+1}. ${esc(o)}</p>`).join('')+'<input id="demoInput" class="search" placeholder="例如 2,3,1">':`<input id="demoInput" class="search" type="number" step="any" placeholder="输入数值">${i===6?'<input id="demoAction" class="search" placeholder="下一步">':''}`)+`<p><button class="btn primary" id="submitDemo">提交答案</button></p><p id="demoFeedback" role="status"></p>`;el('submitDemo').onclick=()=>{let answer,ok=false;if([0,1,3,5].includes(i)){const a=[...document.querySelectorAll('[name=demoChoice]:checked')].map(x=>Number(x.value));if(!a.length)return toast('请先作答');answer=i===1?a:a[0];ok=JSON.stringify(answer)===JSON.stringify(q.answer);}else{if(!el('demoInput').value.trim())return toast('请先作答');if(i===4){answer=el('demoInput').value.split(/[,，]/).map(x=>Number(x.trim())-1);ok=JSON.stringify(answer)===JSON.stringify(q.answer);}else if(i===6){answer={amount:Number(el('demoInput').value),action:el('demoAction').value.trim()};ok=Math.abs(answer.amount-50)<=0.01&&answer.action==='核对';}else{answer=Number(el('demoInput').value);ok=Number.isFinite(answer)&&Math.abs(answer-50)<=0.01;}}record31({id:'DEMO-'+i,answer:q.answer},answer,ok,'demo',{question_type:GT_TYPES[i],knowledge_id:'DEMO-KP-'+i,error_reason:ok?null:i===2?'calculation':'concept'});save();renderMastery31();el('demoFeedback').textContent=ok?'正确。已记录演示作答。':'不正确。请回看题干中的内部规则或公式后再试。';el('submitDemo').disabled=true;};}
