function publicKey31(key){if(key.startsWith('sb_publishable_'))return true;try{const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));return payload.role==='anon';}catch{return false;}}
async function connect31(){try{const url=new URL(el('sbUrl').value.trim()),key=el('sbKey').value.trim();if(url.protocol!=='https:'||!publicKey31(key))throw Error('请填写 HTTPS 项目地址及公开 key');if(sb31)throw Error('切换项目请刷新页面后连接');if(!window.supabase){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.102.0/dist/umd/supabase.js';script.onload=resolve;script.onerror=()=>reject(Error('认证组件载入失败'));document.head.append(script);});}localStorage.setItem('systemESG31:config',JSON.stringify({url:url.origin,key}));sb31=window.supabase.createClient(url.origin,key,{auth:{flowType:'pkce',detectSessionInUrl:true}});sb31.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'&&session){recovery31=true;el('recovery31').hidden=false;go('account');}if(event==='SIGNED_OUT'){recovery31=false;el('recovery31').hidden=true;}setTimeout(()=>applySession31(session),0);});const {data,error}=await sb31.auth.getSession();if(error)throw error;await applySession31(data.session);}catch(e){msg31(e.message);}}
