// One typed renderer/scorer is shared by practice and mock exams.
function type31(q){return q.question_type||'scenario_single';}
function answerText31(q,a=q.correct_answer??q.answer){const t=type31(q);if(t==='integrated_case')return (q.parts||[]).map(p=>(p.q||p.question)+': '+answerText31(p,a?.[p.id])).join('；');if(t==='calculation')return `${a} ${q.unit||''}`;if(Array.isArray(a))return a.map(n=>q.options?.[n]??n).join(t==='decision_order'?' → ':'、');return q.options?.[a]??String(a);}
function grade31(q,a){const correct=q.correct_answer??q.answer,t=type31(q);if(a===undefined||a===null)return false;if(t==='calculation')return typeof a==='number'&&Number.isFinite(a)&&Math.abs(a-Number(correct))<=(q.tolerance??0.01);if(t==='scenario_multiple'){if(!Array.isArray(a)||!Array.isArray(correct))return false;return JSON.stringify([...new Set(a)].sort())===JSON.stringify([...new Set(correct)].sort());}if(t==='integrated_case'){return (q.parts||[]).length>0&&(q.parts||[]).every(p=>grade31(p,a[p.id]));}return JSON.stringify(a)===JSON.stringify(correct);}
function controls31(q,a,prefix='typed'){const t=type31(q);if(t==='integrated_case')return (q.parts||[]).map((p,i)=>`<fieldset><legend>${i+1}. ${esc(p.q||p.question)}</legend>${controls31(p,a?.[p.id],prefix+'_'+i)}</fieldset>`).join('');if(t==='calculation')return `<input class="search" id="${prefix}" type="number" step="any" value="${esc(a??'')}" placeholder="输入数值"> <span>${esc(q.unit||'')}</span>`;if(t==='decision_order')return (q.options||[]).map((o,i)=>`<p>${i+1}. ${esc(o)}</p>`).join('')+`<input class="search" id="${prefix}" value="${esc(Array.isArray(a)?a.map(n=>n+1).join(','):'')}" placeholder="按顺序输入全部编号，以逗号分隔">`;return (q.options||[]).map((o,i)=>`<label class="opt" style="display:block"><input type="${t==='scenario_multiple'?'checkbox':'radio'}" name="${prefix}" value="${i}" ${(Array.isArray(a)?a.includes(i):a===i)?'checked':''}> ${String.fromCharCode(65+i)}. ${esc(o)}</label>`).join('');}
function readTyped31(q,prefix='typed'){const t=type31(q);if(t==='integrated_case'){const a={};(q.parts||[]).forEach((p,i)=>a[p.id]=readTyped31(p,prefix+'_'+i));return a;}if(t==='calculation'){const value=el(prefix).value;if(value==='')throw Error('请填写数值');const a=Number(value);if(!Number.isFinite(a))throw Error('数值无效');return a;}if(t==='decision_order'){const a=el(prefix).value.split(/[,，]/).map(x=>Number(x.trim())-1);if(a.length!==q.options.length||new Set(a).size!==a.length||a.some(n=>!Number.isInteger(n)||n<0||n>=q.options.length))throw Error('请填写全部编号，每项一次');return a;}const a=[...document.querySelectorAll(`[name="${prefix}"]:checked`)].map(x=>Number(x.value));if(!a.length)throw Error('请先选择答案');return t==='scenario_multiple'?a:a[0];}
renderPractice=function(){if(!pool.length){practiceCard.innerHTML='<div class="empty">没有符合当前条件的题目。</div>';return;}const q=pool[pi%pool.length];selected=null;practiceCard.innerHTML=`<div class="tags"><span class="pill">${esc(q.kp)}</span><span class="pill">${esc(q.level)}</span><span class="pill">${GT_LABELS[GT_TYPES.indexOf(type31(q))]}</span><span class="pill">本地练习 / 来源待审核</span></div><div class="q">${esc(q.q)}</div><div class="opts">${controls31(q)}</div><p><button class="btn primary" id="typedSubmit">提交答案</button></p><div id="pAnswer" class="answer"></div><div class="qnav"><small>${pi+1}/${pool.length}</small><button class="btn primary" data-onclick="nextPractice()">下一题</button></div>`;el('typedSubmit').onclick=()=>{try{choosePractice(readTyped31(q));}catch(e){toast(e.message);}};};
choosePractice=function(a){if(selected!==null)return;const q=pool[pi%pool.length],correct=grade31(q,a);selected=a;record31(q,a,correct,'practice',{correct_answer:q.correct_answer??q.answer,question_type:type31(q)});state.answered[q.id]={correct,at:Date.now(),module:q.module,kp:q.kp};if(correct)delete state.wrong[q.id];else state.wrong[q.id]=true;el('pAnswer').textContent=`${correct?'回答正确':'回答错误'} | 答案：${answerText31(q)}。${q.explain||''} 来源：${q.source||'尚未核验'}。`;el('pAnswer').style.display='block';el('typedSubmit').disabled=true;save();renderMastery31();};
renderExamQ=function(){const q=exam.qs[exam.i];examRun.innerHTML=`<div class="card"><div class="mrow"><span>${exam.i+1}/${exam.qs.length} · ${esc(q.kp)}</span><span id="timer"></span></div><div class="q">${esc(q.q)}</div><div class="opts">${controls31(q,exam.ans[q.id],'examTyped')}</div><p id="examSaved">${exam.ans[q.id]!==undefined?'本题已暂存':''}</p><button class="btn soft" id="saveExamTyped">暂存本题</button><div class="qnav"><button class="btn soft" data-onclick="examPrev()">上一题</button><button class="btn soft" data-onclick="examNext()">下一题</button><button class="btn primary" id="submitExam31">交卷</button></div></div>`;el('saveExamTyped').onclick=()=>{try{exam.ans[q.id]=readTyped31(q,'examTyped');el('examSaved').textContent='本题已暂存';}catch(e){toast(e.message);}};el('submitExam31').onclick=()=>{captureExam31();finishExam();};examRun.querySelectorAll('input').forEach(input=>input.addEventListener('change',captureExam31));tick();};
function captureExam31(){if(!exam.qs||exam.completed)return;try{exam.ans[exam.qs[exam.i].id]=readTyped31(exam.qs[exam.i],'examTyped');}catch{}}
examNext=function(){captureExam31();if(exam.i<exam.qs.length-1){exam.i++;renderExamQ();}else toast('已经是最后一题');};
examPrev=function(){captureExam31();if(exam.i>0){exam.i--;renderExamQ();}};
finishExam=function(){if(!exam.qs||exam.completed)return;captureExam31();exam.completed=true;exam.end=null;clearInterval(exam.timer);let correct=0;for(const q of exam.qs){const a=exam.ans[q.id],ok=grade31(q,a);if(ok)correct++;record31(q,a,ok,'exam',{correct_answer:q.correct_answer??q.answer,question_type:type31(q)});state.answered[q.id]={correct:ok,at:Date.now(),module:q.module,kp:q.kp};if(ok)delete state.wrong[q.id];else state.wrong[q.id]=true;}const score=Math.round(correct/exam.qs.length*100);state.exams.push({at:Date.now(),score,n:exam.qs.length});save();renderMastery31();examRun.classList.add('hidden');examResult.classList.remove('hidden');examResult.innerHTML=`<div class="card resultHero"><h3>本地模拟练习结果</h3><div class="score">${score}</div><p>${correct}/${exam.qs.length} 题正确 · 未作答计错</p><button class="btn primary" data-onclick="resetExam()">返回考试首页</button><button class="btn soft" data-onclick="go('ground')">查看弱点与回补建议</button></div>`;};
const typedFinish31=finishExam;
finishExam=function(){if(!exam.qs||exam.completed)return;typedFinish31();const by={};for(const q of exam.qs){by[q.module]??={n:0,c:0};by[q.module].n++;if(grade31(q,exam.ans[q.id]))by[q.module].c++;}examResult.insertAdjacentHTML('beforeend',`<div class="card section"><h3>模块拆解</h3>${Object.entries(by).map(([id,v])=>`<p>${esc(MODULES.find(m=>m.id===id)?.name||id)}：${v.c}/${v.n} · ${Math.round(v.c/v.n*100)}%</p>`).join('')}</div>`);};
